"""Pydantic models and validation for parking configuration (MPS-1)."""

from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal
from typing import Annotated

from pydantic import BaseModel, ConfigDict, condecimal, field_validator

Money = Annotated[
    Decimal,
    condecimal(ge=0, decimal_places=2, max_digits=10),
]


class ConfigurationInput(BaseModel):
    """Validated values accepted by PUT /api/v1/configuration."""

    model_config = ConfigDict(extra="forbid")

    capacity: int
    grace_period_minutes: int
    hourly_rate: Money
    daily_cap: Money
    lost_ticket_fee: Money

    @field_validator("capacity")
    @classmethod
    def capacity_must_be_positive(cls, value: int) -> int:
        if value < 1:
            raise ValueError("capacity must be at least 1")
        return value

    @field_validator("grace_period_minutes")
    @classmethod
    def grace_period_must_be_non_negative(cls, value: int) -> int:
        if value < 0:
            raise ValueError("grace_period_minutes must be zero or greater")
        return value


class ParkingConfiguration(ConfigurationInput):
    """A stored, versioned configuration row."""

    version: int
    pricing_rule_version: int
    active: bool
    created_at: datetime

    def json_ready(self) -> dict:
        return {
            "version": self.version,
            "pricing_rule_version": self.pricing_rule_version,
            "active": self.active,
            "created_at": self.created_at,
            "capacity": self.capacity,
            "grace_period_minutes": self.grace_period_minutes,
            "hourly_rate": str(self.hourly_rate),
            "daily_cap": str(self.daily_cap),
            "lost_ticket_fee": str(self.lost_ticket_fee),
        }


def utcnow() -> datetime:
    return datetime.now(timezone.utc)

"""HTTP API for parking configuration (MPS-1)."""

from __future__ import annotations

from fastapi import APIRouter, HTTPException, Request, status

from .models import ConfigurationInput, ParkingConfiguration
from .storage import ConfigurationStore

router = APIRouter(prefix="/api/v1", tags=["configuration"])


def _store(request: Request) -> ConfigurationStore:
    return request.app.state.configuration_store


@router.get(
    "/configuration/active",
    response_model=dict,
)
def get_active_configuration(request: Request) -> dict:
    config = _store(request).get_active()
    if config is None:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="No active parking configuration exists",
        )
    return config.json_ready()


@router.put(
    "/configuration",
    response_model=dict,
    status_code=status.HTTP_201_CREATED,
)
def upsert_configuration(data: ConfigurationInput, request: Request) -> dict:
    config = _store(request).activate(data)
    return config.json_ready()

